// Build step — NOT part of the app runtime.
// Reads the human-readable data/heritageSites.json (regenerated by
// generate-heritage-data.mjs, hand-edited for nameTr/descriptionTr) and
// writes it, compacted + gzip'd, to assets/heritage/heritage-data.json.gz.
// That's the file data/heritageSites.ts actually loads at runtime — see the
// comment there for why (avoids Hermes bytecode-compiling a ~1.3MB JS object
// literal, and gzip shrinks the JSON text itself by ~70-80%).
//
// Re-run this any time data/heritageSites.json changes (new translations,
// a refreshed UNESCO list, etc.):
//   node scripts/compress-heritage-data.mjs
import { gzipSync } from "node:zlib";
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const SOURCE_PATH = fileURLToPath(
  new URL("../data/heritageSites.json", import.meta.url),
);
const OUTPUT_PATH = fileURLToPath(
  new URL("../assets/heritage/heritage-data.json.gz", import.meta.url),
);

// Wikipedia thumbnail URLs carry Wikipedia-editor tracking params
// (utm_source/utm_campaign/utm_content) that are dead weight for us — they
// don't affect which image loads, they just bloat every row. Strip them.
function stripTrackingParams(imageUrl) {
  if (!imageUrl) return imageUrl;
  return imageUrl.replace(/\?utm_source=.*$/, "");
}

async function main() {
  const raw = await readFile(SOURCE_PATH, "utf8");
  const sites = JSON.parse(raw);

  const cleaned = sites.map((site) => ({
    ...site,
    imageUrl:
      site.imageUrl === undefined
        ? undefined
        : stripTrackingParams(site.imageUrl),
  }));

  const compact = JSON.stringify(cleaned);
  const gzipped = gzipSync(compact, { level: 9 });

  await writeFile(OUTPUT_PATH, gzipped);

  console.log(
    `${sites.length} sites: ${(raw.length / 1024).toFixed(0)}KB source -> ` +
      `${(compact.length / 1024).toFixed(0)}KB compact -> ` +
      `${(gzipped.length / 1024).toFixed(0)}KB gzipped`,
  );
}

main();
